# RW2DM_SHOWSEL: ShowSelected: show hidden objects and select them. The script rw2dm_showsel_script.txt is generated by rw2dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW2_SHOWSEL_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW2_SHOWSEL_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw2dm_showsel_script.txt" 2>&1)" || { echo "$RW2_SHOWSEL_OUT" | tail -40; echo "FAIL RW2DM_SHOWSEL_run: script exited non-zero"; fail=1; RW2_SHOWSEL_OUT=""; }
else
  RW2_SHOWSEL_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw2dm_showsel_script.txt" 2>&1)" || { echo "$RW2_SHOWSEL_OUT" | tail -40; echo "FAIL RW2DM_SHOWSEL_run: script exited non-zero"; fail=1; RW2_SHOWSEL_OUT=""; }
fi
rw2_showsel_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_SHOWSEL_OUT"; }
# rw2_showsel_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw2_showsel_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw2_showsel_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW2DM_SHOWSEL_$name: $desc (objects: $got)"
  else echo "FAIL RW2DM_SHOWSEL_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw2_showsel_state hidden "1:point:Default 4:polysurface:Default" "with 2 and 3 hidden, SelAll reaches only 1 and 4" 
rw2_showsel_state showselected "2:curve:Default 3:surface:Default" "ShowSelected shows the hidden objects and selects exactly them (2 and 3)" 
rw2_showsel_state showall "1:point:Default 2:curve:Default 3:surface:Default 4:polysurface:Default" "after ShowSelected all four are visible: SelAll reaches 1, 2, 3 and 4" 
rw2_showsel_state showselected_one "3:surface:Default" "ShowSelected with only object 3 hidden selects exactly 3" 
